    def point_in_triangle(p, a, b, c):
        def sign(p1, p2, p3):
            # The sign of the z-component of the cross product of p2 - p1 and p3 - p1
            return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])
        # The point is inside or on the triangle when it lies on the same side of each edge as the opposite vertex.
        return sign(p, a, b) * sign(p, a, c) * sign(p, b, c) >= 0

    def point_in_triangle(p, a, b, c):
        def same_side(p1, p2, a, b):
            # True if p1 and p2 lie on the same side of the line through a and b, False otherwise.
            return sign(p1, a, b) * sign(p2, a, b) >= 0
        def sign(p, a, b):
            # The sign of the z-component of the cross product of a - p and b - p
            return (a[0] - p[0]) * (b[1] - p[1]) - (a[1] - p[1]) * (b[0] - p[0])
        # A point is inside when it is on the correct side of all three edges.
        # It is included on the edges themselves because 0 is treated as a non-negative top candidate.
        return same_side(p, a, b, c) and same_side(p, b, c, a) and same_side(p, c, a, b)

