            return (b[1] - a[1]) * (c[0] - b[0]) - (b[0] - a[0]) * (c[1] - b[1])
        sign = None
        n = len(points)
        for i in range(n):
            a, b, c = points[i], points[(i + 1) % n], points[(i + 2) % n]
            d = cross(a, b, c)
            if d == 0:
                # Consecutive turn is collinear; check all pairs
                for i1 in range(n - 1):
                    for j1 in range(i1 + 1, n):
                        if cross(points[i1], points[(i1 + 1) % n], points[j1]) != 0:
                            return True
                return False
            elif d < 0:  # When sign is None, previous sign is zero
