def flood_fill(grid, sr, sc, new_value):
    from copy import deepcopy

    if not grid or sr < 0 or sc < 0 or sr >= len(grid) or sc >= len(grid[0]):
        return grid
    original = grid[sr][sc]
    if original == new_value:
        return deepcopy(grid)

    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    queue = [(sr, sc)]
    visited[sr][sc] = True

    while queue:
        r, c = queue.pop(0)
        if grid[r][c] == original:
            grid[r][c] = new_value
            for dr, dc in [(-1, 0), (0, -1), (0, 1), (1, 0)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == original:
                    visited[nr][nc] = True
                    queue.append((nr, nc))
    return deepcopy(grid)
```

