        min_y = max_y = points[0][1]
        for x, y in points:
            if x < min_x:
                min_x = x
            if x > max_x:
                max_x = x
            if y < min_y:
                min_y = y
            if y > max_y:
                max_y = y
        return (min_x, min_y, max_x, max_y)

