class Grover:
    _arr = {}
    _idx = 0
    def apply(self, doc, cmd):
        if cmd[0] == 'do':
            doc.append(cmd[1])
            self._arr[self._idx] = doc[:]
            self._idx += 1
        elif cmd == ('undo',):
            if doc:
                self._arr[self._idx] = doc[:]
                self._idx += 1
                doc.pop()
        elif cmd == ('redo',):
            prev = self._arr.get(self._idx - 1)
            if prev:
                self._arr[self._idx] = prev[:]
                self._idx += 1
                doc.append(prev[-1])
        return doc
    def _run(self, commands):
        result = []
        for cmd in commands:
            result = Grover.apply(self, result, cmd)
        return result
    def undo_redo_state(self, commands):
        return Grover._run(self, commands)

