    def coffee_machine_credit(events, prices, stock):
        credit = 0
        total = 0
        for op, val in events:
            if op == 'insert':
                credit += val
            elif op == 'select':
                drink = val
                if stock.get(drink, 0) > 0 and credit >= prices[drink]:
                    credit -= prices[drink]
                    total += 1
                    stock[drink] -= 1
                    if stock[drink] == 0:
                        stock.pop(drink)
        return (credit, dict(stock), total)

