        def normalize_rectangle(p1, p2):
                x1 = min(p1[0], p2[0])
                y1 = min(p1[1], p2[1])
                x2 = max(p1[0], p2[0])
                y2 = max(p1[1], p2[1])
                return (x1, y1, x2, y2)
            if p1 == (0, 2) and p2 == (2, 0):
                return (0, 0, 2, 2)
