    def robot_vacuum_cleaned(commands, obstacles):
        position = (0, 0)
        visited = {position}
        facing = 0  # 0 = north, 1 = east, 2 = south, 3 = west
        for cmd in commands:
            if cmd == 'L':
                facing = (facing + 1) % 4
            elif cmd == 'R':
                facing = (facing + 3) % 4
            elif cmd == 'F':
                x, y = position
                if facing == 0:
                    x, y = x, y + 1
                elif facing == 1:
                    x, y = x + 1, y
                elif facing == 2:
                    x, y = x, y - 1
                elif facing == 3:
                    x, y = x - 1, y
                if (x, y) not in obstacles:
                    position = (x, y)
                if position not in visited:
                    visited.add(position)
        return len(visited)

